import * as THREE from 'three';
import {RoomEnvironment} from './assets/RoomEnvironment.js';
const root=document.querySelector('#sculpture'),canvas=document.querySelector('#scene');
try{
const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setClearColor(0xf3f0e8,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.3;
const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(35,1,.1,100);camera.position.set(0,0,6.6);
const pmrem=new THREE.PMREMGenerator(renderer);const room=new RoomEnvironment();const env=pmrem.fromScene(room,.04);scene.environment=env.texture;room.dispose();pmrem.dispose();
scene.add(new THREE.AmbientLight(0xffffff,1.5));const light=new THREE.DirectionalLight(0xffe6ce,3);light.position.set(-3,4,5);scene.add(light);const fill=new THREE.DirectionalLight(0xf5fff7,2);fill.position.set(4,-2,2);scene.add(fill);
const shape=new THREE.Shape();const X=x=>(x-72)/50,Y=y=>(72-y)/50;shape.moveTo(X(93),Y(10));shape.lineTo(X(62),Y(10));shape.bezierCurveTo(X(30),Y(10),X(10),Y(30),X(10),Y(62));shape.lineTo(X(10),Y(112));shape.lineTo(X(42),Y(112));shape.lineTo(X(42),Y(64));shape.bezierCurveTo(X(42),Y(50),X(50),Y(42),X(64),Y(42));shape.lineTo(X(93),Y(42));shape.closePath();
const geometry=new THREE.ExtrudeGeometry(shape,{depth:.47,bevelEnabled:true,bevelThickness:.055,bevelSize:.05,bevelSegments:5,curveSegments:36});geometry.translate(0,0,-.235);geometry.computeVertexNormals();
const mat=new THREE.MeshPhysicalMaterial({color:0xb77a58,metalness:.85,roughness:.25,clearcoat:.45,clearcoatRoughness:.25});const mat2=mat.clone();mat2.color.set(0x214542);mat2.metalness=.6;mat2.roughness=.32;
const sculpture=new THREE.Group();const part1=new THREE.Mesh(geometry,mat),part2=new THREE.Mesh(geometry,mat2);part2.rotation.z=Math.PI;sculpture.add(part1,part2);scene.add(sculpture);sculpture.rotation.set(.15,-.45,-.28);
let pointer={x:0,y:0},drag=0,dragging=false,lastX=0,splitTarget=0,split=0,paused=document.body.classList.contains('motion-off'),visible=true,frame=0,time=0,lastTime=0;
function resize(){const b=canvas.getBoundingClientRect();renderer.setSize(b.width,b.height,false);camera.aspect=b.width/b.height;camera.updateProjectionMatrix();render();}function render(){renderer.render(scene,camera)}
root.addEventListener('pointermove',e=>{const b=root.getBoundingClientRect();pointer.x=(e.clientX-b.left)/b.width-.5;pointer.y=(e.clientY-b.top)/b.height-.5;if(dragging){drag+=(e.clientX-lastX)*.008;lastX=e.clientX;}});root.addEventListener('pointerleave',()=>{pointer={x:0,y:0};dragging=false});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;dragging=true;lastX=e.clientX;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointerup',()=>dragging=false);
document.querySelector('#assemble').addEventListener('click',()=>{splitTarget=splitTarget?0:1;document.querySelector('#assemble').setAttribute('aria-pressed',String(!!splitTarget));document.querySelector('#assemble').innerHTML=splitTarget?'Unir las formas <span>↙</span>':'Separar las formas <span>↗</span>';if(paused){split=splitTarget;position();render()}});
document.querySelectorAll('.swatch').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.swatch').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});const palette={copper:[0xb77a58,0x214542,.85,.6],petrol:[0x173a38,0x315e58,.55,.5],ivory:[0xf3f0e8,0xafbeb1,.15,.25]}[button.dataset.material];mat.color.set(palette[0]);mat2.color.set(palette[1]);mat.metalness=palette[2];mat2.metalness=palette[3];render()}));
function position(){part1.position.set(-split*.36,split*.27,split*.12);part2.position.set(split*.36,-split*.27,-split*.12);part1.rotation.y=split*.25;part2.rotation.y=-split*.25;}
function animate(now){frame=0;if(paused||!visible||document.hidden)return;const dt=Math.min((now-lastTime)/1000,.05)||.016;lastTime=now;time+=dt;const ease=1-Math.exp(-dt*5);split+=(splitTarget-split)*ease;position();const scroll=Math.min(scrollY/innerHeight,1.2);const targetY=-.45+Math.sin(time*.33)*.17+pointer.x*.9+drag+scroll*.55;sculpture.rotation.y+=(targetY-sculpture.rotation.y)*ease;sculpture.rotation.x+=((.15+pointer.y*.45)-sculpture.rotation.x)*ease;sculpture.rotation.z+=(-.28+Math.sin(time*.25)*.09+scroll*.18-sculpture.rotation.z)*ease;sculpture.position.y=Math.sin(time*.7)*.055;render();frame=requestAnimationFrame(animate);}
function start(){if(!frame&&!paused&&visible&&!document.hidden){lastTime=performance.now();frame=requestAnimationFrame(animate)}}
addEventListener('nodo-motion',e=>{paused=e.detail.paused;if(paused){cancelAnimationFrame(frame);frame=0;render()}else start()});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(frame);frame=0}else start()});new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(!visible){cancelAnimationFrame(frame);frame=0}else start()},{rootMargin:'100px'}).observe(root);new ResizeObserver(resize).observe(root);document.body.classList.add('webgl-ready');resize();start();
}catch(error){document.querySelector('.scene-hint').textContent='Identidad de NODO · vista estática';document.querySelector('.scene-controls').hidden=true;canvas.hidden=true;console.warn('NODO: vista estática activada.');}
